SELECT user_id, daily_advid, daily_dt, media, target_id, target_name,
       level, type, content, daily_regdate
FROM h3_budget_alarm

    user_id = #{userId}

        AND daily_dt BETWEEN #{fromdate} AND #{todate}


ORDER BY daily_dt DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM h3_budget_alarm

    user_id = #{userId}

        AND daily_dt BETWEEN #{fromdate} AND #{todate}

SELECT A.user_id, A.daily_advid, A.daily_dt, A.media, A.target_id, A.target_name, A.level, A.type, A.content, A.daily_regdate, S.user_manager AS manager_id, U.user_name AS manager_name FROM h3_budget_alarm A LEFT JOIN h3_share S ON S.user_id = A.user_id LEFT JOIN h3_users U ON U.user_id = S.user_manager
A.daily_dt BETWEEN #{fromdate} AND #{todate}
ORDER BY A.daily_dt DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM h3_budget_alarm A


        A.daily_dt BETWEEN #{fromdate} AND #{todate}

